package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Exact identity queue for indexed content lacking source-bound mechanics or a reachable effect pipeline. */
public final class ExactMissingContentQueueEngine{
 private ExactMissingContentQueueEngine(){}
 public static JSONObject report(){JSONObject o=new JSONObject();JSONArray q=new JSONArray();try{add(q,"subclass",CharacterOptionCatalogEngine.allSubclasses());add(q,"feat",CharacterOptionCatalogEngine.allFeats());add(q,"spell",SpellItemCatalogEngine.all("spell"));add(q,"item",SpellItemCatalogEngine.all("item"));JSONObject b=AuthorizedBestiaryScopeEngine.coverage();if(!b.optBoolean("target_known",false))q.put(new JSONObject().put("kind","statblock_scope").put("status","waiting_authorized_scope"));else{JSONArray m=b.optJSONArray("missing_ids");for(int i=0;m!=null&&i<m.length();i++)q.put(new JSONObject().put("kind","statblock").put("name",m.optString(i)).put("status","waiting_authorized_mechanics"));}
  JSONObject books=BookMechanicsScopeEngine.coverage();if(!books.optBoolean("complete",false))q.put(new JSONObject().put("kind","book_scope").put("status","waiting_book_mechanics_review").put("in_scope_entries",books.optInt("in_scope_entries",0)).put("excluded_mystara_prefix_entries",books.optInt("excluded_mystara_prefix_entries",0)));return o.put("queue",q).put("count",q.length()).put("release_blocked",q.length()>0).put("exact_indexed_identities",true).put("source_bound_is_not_effect_complete",true);}catch(Exception e){return o;}}
 private static void add(JSONArray q,String kind,JSONArray ids)throws Exception{for(int i=0;i<ids.length();i++){String n=ids.optString(i);if(!CompiledContentMechanicsEngine.has(kind,n))q.put(new JSONObject().put("kind",kind).put("name",n).put("status","waiting_authorized_mechanics"));else if(!CompiledContentMechanicsEngine.hasEffectPipeline(kind,n))q.put(new JSONObject().put("kind",kind).put("name",n).put("status","waiting_effect_pipeline"));}}
}
